"""Trace designated regression cases without affecting candidate selection."""
def cases(audit,rows,cache,borrow_targets,intraday_targets,research,now):
    records={s['ticker']:(s,a) for s,a in rows};borrow={s['ticker'] for s in borrow_targets};intra={s['ticker'] for s in intraday_targets};rank={s['ticker']:i+1 for i,(s,a) in enumerate(research)}
    score_rank={s['ticker']:i+1 for i,(s,a) in enumerate(sorted(rows,key=lambda x:((x[1].get('observed_score') if x[1].get('observed_score') is not None else -1),x[1].get('coverage',0)),reverse=True))}
    eligible=[(s,a) for s,a in rows if a.get('candidate_type')=='short_verified' and a.get('candidate') and not a.get('high_risk') and s.get('halt_status') in ('no_halt_detected','resumed')]
    qualified_rank={s['ticker']:i+1 for i,(s,a) in enumerate(sorted(eligible,key=lambda x:((x[1].get('observed_score') if x[1].get('observed_score') is not None else -1),x[1].get('coverage',0)),reverse=True))}
    output=[]
    for ticker in ('SHFS','NCPL'):
        entry=audit.get(ticker,{});stock,analysis=records.get(ticker,({},{}));obs=cache.get(ticker,{});b=obs.get('borrow',{});si=obs.get('short_interest',{})
        reason=entry.get('scope_reason') or ('연구 TOP10' if ticker in rank else '검증 숏 후보 점수순 '+str(qualified_rank[ticker])+'위; 상위10 외' if ticker in qualified_rank else '즉시 희석 위험 별도 관찰' if analysis.get('high_risk') else '거래정지 상태 검증 대기' if stock and stock.get('halt_status') not in ('no_halt_detected','resumed') else '가격 선행 별도 관찰; 숏 후보 요건 미확인' if analysis.get('candidate_type')=='market_watch' else '최신 가격·숏 신호2개·숏 확인배점8·전체 확인배점45 요건 미충족')
        output.append({'ticker':ticker,'name':entry.get('name',obs.get('name')),'observed_at':now.isoformat(),'listed':entry.get('listed',False),'scope_reason':entry.get('scope_reason'),'daily_received':entry.get('daily_received',False),'price_as_of':entry.get('price_as_of'),'borrow_attempted':ticker in borrow,'borrow_source':b.get('source'),'borrow_as_of':b.get('as_of'),'borrow_observed_at':b.get('observed_at'),'ctb':b.get('ctb'),'available':b.get('available'),'official_interest_valid':analysis.get('official_interest',{}).get('scoring_valid'),'official_interest_source':si.get('source'),'official_interest_observed_at':si.get('observed_at'),'dollar_ratio':analysis.get('market',{}).get('dollar_ratio'),'market_as_of':analysis.get('market',{}).get('as_of'),'intraday_attempted':ticker in intra,'intraday_as_of':analysis.get('intraday',{}).get('as_of'),'score':analysis.get('observed_score'),'coverage':analysis.get('coverage'),'stage':analysis.get('stage'),'candidate':analysis.get('candidate',False),'candidate_type':analysis.get('candidate_type'),'early_signal':analysis.get('early_signal'),'research_rank':rank.get(ticker),'observation_score_rank':score_rank.get(ticker),'qualified_short_rank':qualified_rank.get(ticker),'top10_reason':reason,'historical_verdict':'검증 불가: 당시 확보된 시점별 CTB·전체 시세·계약 스냅샷 없이 조기 포착을 소급 주장하지 않음'})
    return output
